const item = $input.item.json;

const texto = (valor) =>
  typeof valor === 'string' ? valor.trim() : '';

const errores = [];

const estado = texto(item.property_estado);
const asunto = texto(item.property_asunto_aprobado);
const contenido = texto(item.property_contenido_aprobado);
const email = texto(item.property_email_destinatario);
const idEnvio = texto(item.property_id_envio);

const version = Number(item.property_version);
const fechaAprobacion = item.property_fecha_aprobacion?.start;

const aprobadoPor = item.property_aprobado_por;

const tieneAprobador =
  Array.isArray(aprobadoPor)
    ? aprobadoPor.length > 0
    : Boolean(aprobadoPor);

if (estado !== 'Aprobado') {
  errores.push('El contenido no está aprobado');
}

if (!asunto) {
  errores.push('Falta el asunto aprobado');
}

if (!contenido) {
  errores.push('Falta el contenido aprobado');
}

if (!Number.isInteger(version) || version < 1) {
  errores.push('La versión no es válida');
}

if (!fechaAprobacion) {
  errores.push('Falta la fecha de aprobación');
}

if (!tieneAprobador) {
  errores.push('Falta identificar al responsable de la aprobación');
}

if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  errores.push('El correo del destinatario no es válido');
}

if (idEnvio) {
  errores.push('El contenido ya tiene un identificador de envío');
}

return {
  json: {
    ...item,
    validacion_aprobacion: {
      es_valida: errores.length === 0,
      errores,
      version_validada: version
    }
  }
};

const item = $input.item.json;

const texto = (valor) =>
  typeof valor === 'string' ? valor.trim() : '';

const errores = [];

if (item.property_estado !== 'Aprobado') {
  errores.push('El contenido ya no está aprobado');
}

if (!texto(item.property_asunto_aprobado)) {
  errores.push('Falta el asunto aprobado');
}

if (!texto(item.property_contenido_aprobado)) {
  errores.push('Falta el contenido aprobado');
}

if (!item.property_fecha_aprobacion?.start) {
  errores.push('Falta la fecha de aprobación');
}

const aprobadores = item.property_aprobado_por;

if (
  Array.isArray(aprobadores)
    ? aprobadores.length === 0
    : !aprobadores
) {
  errores.push('Falta el responsable de aprobación');
}

const versionValidada = $(
  'B-03 | Validación | Verificar aprobación'
).first().json.validacion_aprobacion.version_validada;

if (Number(item.property_version) !== versionValidada) {
  errores.push('La versión no coincide con la versión validada');
}

if (texto(item.property_id_envio)) {
  errores.push('El contenido ya registra un envío');
}

const emailAutorizado = String(
  $('B-00 | Config | Parametros de envio')
    .first().json.email_autorizado ?? ''
).trim().toLowerCase();

if (
  !emailAutorizado ||
  texto(item.property_email_destinatario).toLowerCase() !== emailAutorizado
) {
  errores.push('El destinatario no está autorizado o falta configurar el correo autorizado');
}

return {
  json: {
    ...item,
    validacion_final: {
      es_valida: errores.length === 0,
      errores
    }
  }
};

const item = $input.item.json;

const idContenido = item.id;
const version = Number(item.property_version);

const idIntento = `ENV-${idContenido}-V${version}`;

return {
  json: {
    ...item,
    control_envio: {
      id_intento: idIntento,
      version,
      estado: 'Preparado'
    }
  }
};
